pragma solidity >=0.8.0;
contract GasProbe {
    uint256 public entryGas;
    uint256 public exitGas;
    uint256 public entryNorm;
    uint256 public exitNorm;
    event GasRecorded(uint256 entryG, uint256 exitG);
    function getGas() public view returns (uint256) {
        return gasleft() / 16;
    }
    function recordEntry() public {
        entryGas = gasleft();
        entryNorm = entryGas / 16;
        uint256 s = 0;
        for (uint256 i = 0; i < 16; i++) {
            s += (i >> 1) + (i * 3);
        }
        exitGas = gasleft();
        exitNorm = exitGas / 16;
        emit GasRecorded(entryGas, exitGas);
    }
}
